{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2131-03-02 08:30:00",
      "speaker": "Doctor",
      "text": "Good morning, Mr. Thompson. I'm Dr. Patel, one of your hospitalists. You're here today for your maintenance high-dose methotrexate infusion, correct?"
    },
    {
      "turn_number": 2,
      "time": "2131-03-02 08:31:00",
      "speaker": "Patient",
      "text": "Yes, that’s right. This is the ninth cycle since the relapse, right?"
    },
    {
      "turn_number": 3,
      "time": "2131-03-02 08:32:00",
      "speaker": "Doctor",
      "text": "Exactly. It’s your fifth maintenance dose and second one given every two months. You’ve been doing well so far."
    },
    {
      "turn_number": 4,
      "time": "2131-03-02 08:33:00",
      "speaker": "Patient",
      "text": "Good. I’ve been feeling okay. No headaches or weakness like before."
    },
    {
      "turn_number": 5,
      "time": "2131-03-02 08:34:00",
      "speaker": "Doctor",
      "text": "That’s reassuring. We’ll monitor you closely. Before the infusion, we need to check your labs and vital signs."
    },
    {
      "turn_number": 6,
      "time": "2131-03-02 08:35:00",
      "speaker": "Patient",
      "text": "Of course. Any reason to worry?"
    },
    {
      "turn_number": 7,
      "time": "2131-03-02 08:36:00",
      "speaker": "Doctor",
      "text": "Your labs this morning look stable. White count is normal, kidney function is good. We did see a slightly prolonged PTT, but it’s not concerning given your history."
    },
    {
      "turn_number": 8,
      "time": "2131-03-02 08:37:00",
      "speaker": "Patient",
      "text": "I remember that from last time. It always runs a bit high."
    },
    {
      "turn_number": 9,
      "time": "2131-03-02 08:38:00",
      "speaker": "Doctor",
      "text": "Yes, likely due to your underlying condition. We’ll keep an eye on it, but no action needed now."
    },
    {
      "turn_number": 10,
      "time": "2131-03-02 10:00:00",
      "speaker": "Doctor",
      "text": "We’ve reviewed your labs, and everything looks good. You’re cleared for the methotrexate infusion today."
    },
    {
      "turn_number": 11,
      "time": "2131-03-02 10:01:00",
      "speaker": "Patient",
      "text": "Great. When will it start?"
    },
    {
      "turn_number": 12,
      "time": "2131-03-02 10:02:00",
      "speaker": "Doctor",
      "text": "In about an hour. The pharmacy is preparing it. We’ll give it through your port, and you’ll be monitored the whole time."
    },
    {
      "turn_number": 13,
      "time": "2131-03-02 10:03:00",
      "speaker": "Patient",
      "text": "And the rituximab? Wasn’t that supposed to be around this time?"
    },
    {
      "turn_number": 14,
      "time": "2131-03-02 10:04:00",
      "speaker": "Doctor",
      "text": "You already received rituximab as an outpatient a few days ago. So today is just the methotrexate."
    },
    {
      "turn_number": 15,
      "time": "2131-03-02 10:05:00",
      "speaker": "Patient",
      "text": "Ah, right. I forgot. That makes sense."
    },
    {
      "turn_number": 16,
      "time": "2131-03-02 12:15:00",
      "speaker": "Doctor",
      "text": "Hi again. The methotrexate infusion started 15 minutes ago. How are you feeling?"
    },
    {
      "turn_number": 17,
      "time": "2131-03-02 12:16:00",
      "speaker": "Patient",
      "text": "Fine so far. No nausea or dizziness."
    },
    {
      "turn_number": 18,
      "time": "2131-03-02 12:17:00",
      "speaker": "Doctor",
      "text": "Good. We’ll continue to monitor. We’ve held your aspirin and omeprazole during this time to reduce risks."
    },
    {
      "turn_number": 19,
      "time": "2131-03-02 12:18:00",
      "speaker": "Patient",
      "text": "I remember. Last time you said it’s safer that way."
    },
    {
      "turn_number": 20,
      "time": "2131-03-02 12:19:00",
      "speaker": "Doctor",
      "text": "Exactly. We’ll restart them once you’re ready to go home."
    },
    {
      "turn_number": 21,
      "time": "2131-03-03 09:00:00",
      "speaker": "Doctor",
      "text": "Morning, Mr. Thompson. Your infusion finished yesterday, and you’ve had a quiet night. We’ll check your methotrexate level today."
    },
    {
      "turn_number": 22,
      "time": "2131-03-03 09:01:00",
      "speaker": "Patient",
      "text": "Is that to make sure it’s out of my system?"
    },
    {
      "turn_number": 23,
      "time": "2131-03-03 09:02:00",
      "speaker": "Doctor",
      "text": "Yes. We need to confirm it’s low enough before discharge. It was 1.8 last evening — a bit high, but expected."
    },
    {
      "turn_number": 24,
      "time": "2131-03-03 09:03:00",
      "speaker": "Patient",
      "text": "And when does it become safe?"
    },
    {
      "turn_number": 25,
      "time": "2131-03-03 09:04:00",
      "speaker": "Doctor",
      "text": "We aim for under 0.1. We’ll test again tomorrow morning. If it’s down, you can go home."
    },
    {
      "turn_number": 26,
      "time": "2131-03-03 09:05:00",
      "speaker": "Patient",
      "text": "Okay, sounds good. My chest rash seems better too."
    },
    {
      "turn_number": 27,
      "time": "2131-03-03 09:06:00",
      "speaker": "Doctor",
      "text": "Yes, the candidal rash has improved significantly. We’ll keep you on miconazole cream instead of fluconazole."
    },
    {
      "turn_number": 28,
      "time": "2131-03-03 09:07:00",
      "speaker": "Patient",
      "text": "Is it fungal then?"
    },
    {
      "turn_number": 29,
      "time": "2131-03-03 09:08:00",
      "speaker": "Doctor",
      "text": "Yes, likely candida. The cream should keep it under control."
    },
    {
      "turn_number": 30,
      "time": "2131-03-04 07:30:00",
      "speaker": "Doctor",
      "text": "Good news — your methotrexate level is now 0.10, which is safe. We’re on track for discharge tomorrow."
    },
    {
      "turn_number": 31,
      "time": "2131-03-04 07:31:00",
      "speaker": "Patient",
      "text": "That’s great. Any other tests?"
    },
    {
      "turn_number": 32,
      "time": "2131-03-04 07:32:00",
      "speaker": "Doctor",
      "text": "We did a brain MRI yesterday to check for any changes. The report isn’t back yet, but the imaging is stable compared to last time."
    },
    {
      "turn_number": 33,
      "time": "2131-03-04 07:33:00",
      "speaker": "Patient",
      "text": "No new tumors or anything?"
    },
    {
      "turn_number": 34,
      "time": "2131-03-04 07:34:00",
      "speaker": "Doctor",
      "text": "No enhancing lesions — that’s a good sign. No evidence of recurrence."
    },
    {
      "turn_number": 35,
      "time": "2131-03-04 07:35:00",
      "speaker": "Patient",
      "text": "Thank you. That’s a relief."
    },
    {
      "turn_number": 36,
      "time": "2131-03-04 07:36:00",
      "speaker": "Doctor",
      "text": "Your liver enzymes are a bit elevated — AST and ALT are up — but that’s common after methotrexate and should resolve."
    },
    {
      "turn_number": 37,
      "time": "2131-03-04 07:37:00",
      "speaker": "Patient",
      "text": "Should I be worried?"
    },
    {
      "turn_number": 38,
      "time": "2131-03-04 07:38:00",
      "speaker": "Doctor",
      "text": "Not at this point. We’ll monitor them over time, but they’re expected to come down."
    },
    {
      "turn_number": 39,
      "time": "2131-03-04 07:39:00",
      "speaker": "Patient",
      "text": "Okay, good. And my heart medications?"
    },
    {
      "turn_number": 40,
      "time": "2131-03-04 07:40:00",
      "speaker": "Doctor",
      "text": "You’ll restart aspirin and omeprazole tomorrow. We held them during treatment for safety."
    },
    {
      "turn_number": 41,
      "time": "2131-03-04 07:41:00",
      "speaker": "Patient",
      "text": "Makes sense. I’ve been using the docusate and magnesium as needed."
    },
    {
      "turn_number": 42,
      "time": "2131-03-04 07:42:00",
      "speaker": "Doctor",
      "text": "Good. Keep that up. No constipation so far?"
    },
    {
      "turn_number": 43,
      "time": "2131-03-04 07:43:00",
      "speaker": "Patient",
      "text": "None. I’ve been walking every day."
    },
    {
      "turn_number": 44,
      "time": "2131-03-04 07:44:00",
      "speaker": "Doctor",
      "text": "Excellent. That helps with everything — circulation, digestion, mood."
    },
    {
      "turn_number": 45,
      "time": "2131-03-05 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re cleared to go home today. Your labs are stable, methotrexate is cleared, and you’re feeling well."
    },
    {
      "turn_number": 46,
      "time": "2131-03-05 08:01:00",
      "speaker": "Patient",
      "text": "That’s great. What about the MRI results?"
    },
    {
      "turn_number": 47,
      "time": "2131-03-05 08:02:00",
      "speaker": "Doctor",
      "text": "The radiologist reviewed it — no new lesions, no signs of recurrence. The old lesion is stable and not enhancing."
    },
    {
      "turn_number": 48,
      "time": "2131-03-05 08:03:00",
      "speaker": "Patient",
      "text": "That’s a huge relief. Thank you."
    },
    {
      "turn_number": 49,
      "time": "2131-03-05 08:04:00",
      "speaker": "Doctor",
      "text": "We’ll follow up with your oncologist. Your next methotrexate dose is scheduled in two months."
    },
    {
      "turn_number": 50,
      "time": "2131-03-05 08:05:00",
      "speaker": "Patient",
      "text": "And I’ll get rituximab in clinic before that?"
    },
    {
      "turn_number": 51,
      "time": "2131-03-05 08:06:00",
      "speaker": "Doctor",
      "text": "Yes, the team will contact you to schedule it. Keep using the miconazole for the rash, and restart your regular meds today."
    },
    {
      "turn_number": 52,
      "time": "2131-03-05 08:07:00",
      "speaker": "Patient",
      "text": "I will. Thanks for all the care."
    },
    {
      "turn_number": 53,
      "time": "2131-03-05 08:08:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Call if you have fever, severe nausea, or any neurological symptoms. Otherwise, see you in two months."
    },
    {
      "turn_number": 54,
      "time": "2131-03-05 08:09:00",
      "speaker": "Patient",
      "text": "Will do. Have a good day."
    },
    {
      "turn_number": 55,
      "time": "2131-03-05 08:10:00",
      "speaker": "Doctor",
      "text": "You too. Take care."
    },
    {
      "turn_number": 56,
      "time": "2131-03-05 10:30:00",
      "speaker": "Doctor",
      "text": "Just a quick check-in before discharge. Any last questions?"
    },
    {
      "turn_number": 57,
      "time": "2131-03-05 10:31:00",
      "speaker": "Patient",
      "text": "No, I think we covered everything. I feel ready to go home."
    },
    {
      "turn_number": 58,
      "time": "2131-03-05 10:32:00",
      "speaker": "Doctor",
      "text": "Perfect. Your wife will be here soon to pick you up?"
    },
    {
      "turn_number": 59,
      "time": "2131-03-05 10:33:00",
      "speaker": "Patient",
      "text": "Yes, she’s on her way."
    },
    {
      "turn_number": 60,
      "time": "2131-03-05 10:34:00",
      "speaker": "Doctor",
      "text": "Great. We’ll have your discharge papers ready shortly."
    },
    {
      "turn_number": 61,
      "time": "2131-03-05 12:00:00",
      "speaker": "Doctor",
      "text": "Here’s your discharge summary. You’re doing well — no complications from the infusion."
    },
    {
      "turn_number": 62,
      "time": "2131-03-05 12:01:00",
      "speaker": "Patient",
      "text": "Thank you. I appreciate all the attention to detail."
    },
    {
      "turn_number": 63,
      "time": "2131-03-05 12:02:00",
      "speaker": "Doctor",
      "text": "Our pleasure. Stay active, keep up with your bowel regimen, and we’ll see you next cycle."
    },
    {
      "turn_number": 64,
      "time": "2131-03-05 12:03:00",
      "speaker": "Patient",
      "text": "I will. Take care."
    },
    {
      "turn_number": 65,
      "time": "2131-03-05 12:04:00",
      "speaker": "Doctor",
      "text": "You too. Safe travels home."
    },
    {
      "turn_number": 66,
      "time": "2131-03-05 15:00:00",
      "speaker": "Doctor",
      "text": "Final check — all set for discharge?"
    },
    {
      "turn_number": 67,
      "time": "2131-03-05 15:01:00",
      "speaker": "Patient",
      "text": "Yes, all good. Ready to go."
    }
  ],
  "summary": {
    "admission_start": "2131-03-02 00:00:00",
    "admission_end": "2131-03-05 18:26:00",
    "summary_paragraph": "Mr. Thompson was admitted for his ninth cycle of high-dose methotrexate since CNS lymphoma relapse, marking the fifth maintenance dose and second bimonthly administration. He tolerated the chemotherapy infusion well without complications. His candidal chest rash improved with topical miconazole, and he remained neurologically stable with no new deficits. Methotrexate levels were monitored and cleared appropriately. Liver enzymes rose transiently as expected. Aspirin and omeprazole were held during treatment and restarted at discharge. A brain MRI showed no new enhancing lesions, indicating stable disease. He was discharged home in stable condition with follow-up scheduled for the next cycle in two months.",
    "problems": [
      "Encounter for antineoplastic chemotherapy",
      "Other malignant lymphomas, lymph nodes of multiple sites",
      "Other and unspecified hyperlipidemia",
      "Esophageal reflux",
      "Candidiasis of skin and nails",
      "Coronary atherosclerosis of native coronary artery",
      "Personal history of tuberculosis",
      "Long-term (current) use of aspirin",
      "Headache",
      "Constipation, unspecified"
    ]
  }
}
